  "scenario": "A person is interviewing for a job as a lawyer",
  "agents": [
    {
      "name": "Interviewer",
      "role": "Hiring manager",
      "goal": "Assess the candidate's legal knowledge and communication skills",
      "constraints": ["Evaluate based on prepared questions", "Maintain professional demeanor"]
    },
    {
      "name": "Candidate",
      "role": "Job applicant",
      "goal": "Demonstrate legal expertise and suitability for the role",
      "constraints": ["Answer questions without prior knowledge of the interviewer's questions", "Respond within 30 seconds per question"]
    },
    {
      "name": "Recruiter",
      "role": "HR representative",
      "goal": "Evaluate the candidate's cultural fit and overall impression",
      "constraints": ["Provide feedback on non-legal aspects", "Avoid influencing the interviewer's assessment"]
    }
  ],
  "outcome": {
    "name": "Hiring decision",
    "operationalization": "Whether the candidate is offered the job or not",
    "measurement_question": "Was the candidate selected for the position?",
    "respondent": "Recruiter"
  },
  "causes": [
    {
      "name": "Legal knowledge",
      "hypothesis": "Higher legal knowledge leads to better performance in the interview",
      "predicted_direction": "increase",
      "treatment_values": ["Basic legal principles", "Advanced legal case analysis", "Real-world legal scenarios"]
    },
    {
      "name": "Communication clarity",
      "hypothesis": "Clear communication improves the candidate's impression on the interviewer",
      "predicted_direction": "increase",
      "treatment_values": ["Confusing explanations", "Structured and concise responses", "Use of legal jargon"]
    },
    {
      "name": "Cultural fit",
      "hypothesis": "Candidates with better cultural fit are more likely to be hired",
      "predicted_direction": "increase",
      "treatment_values": ["High alignment with firm values", "Moderate alignment", "Low alignment"]
    }
  ],
  "information_scope": {
    "public": ["Interview questions", "Candidate's resume", "Firm's core values"],
    "private": [
      {
        "agent": "Interviewer",
        "information": ["Previous interview notes", "Internal hiring criteria", "Candidate's past performance"]
      },
      {
        "agent": "Candidate",
        "information": ["Interviewer's past hiring decisions", "Recruiter's feedback history", "Firm's salary range"]
      },
      {
        "agent": "Recruiter",
        "information": ["Internal hiring timeline", "Candidate's interview history", "Firm's diversity metrics"]
      }
    ]
  },
  "interaction": {
    "order": ["Interviewer", "Candidate", "Recruiter"],
    "max_turns": 3,
    "stopping_rule": "The interaction stops after the recruiter provides the hiring decision"
  }
}

